{
  "interpretation": {
    "name": "CalibrateSharedNutrunnerBeforeLine2Use",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Make the shared nutrunner NR7 ready for line 2 and use it for the F30 fasteners. Calibration was requested but no calibration service exists, so only the use of the tool is planned.",
    "constraints": [
      "Calibration of NR7 must happen before line 2 uses the tool, but no calibration service is available, so it cannot be part of the Recipe",
      "NR7 is shared, so it must be reserved before use and released afterwards",
      "NR7 must be at st2 (transport-tool to station completed) before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program for variant F30",
      "The tightening must be evaluated and recorded",
      "Every tool-using Step renews the lease and therefore depends on reserve-tool"
    ],
    "preference": "Return NR7 to the crib after use so that other lines can obtain it.",
    "priority": "normal",
    "horizon": "Next use of NR7 by line 2",
    "requested_capabilities": ["calibrate-tool"],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-nr7-f30-tightening",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "move-to-station",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "move-to-station",
        "next": "tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "tighten",
        "next": "verify",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["tighten-bolts"], "dep": ["program", "reserve"], "executor": null, "params": {}},
          {"name": "tighten-bolts", "service": "tighten-fasteners", "next": [], "dep": ["configure", "reserve"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "verify",
        "next": "move-to-crib",
        "steps": [
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["tighten-bolts", "program"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten-bolts"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "move-to-crib",
        "next": "finish",
        "steps": [
          {"name": "transport-to-crib", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "crib"}}
        ]
      },
      {
        "name": "finish",
        "next": null,
        "steps": [
          {"name": "release", "service": "release-tool", "next": [], "dep": ["reserve"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
